pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        TransferFromOnlyCallee callee = new TransferFromOnlyCallee();
        vm.prank(from);
        c.transfer(from, address(callee), _tos, v);
        assertTrue(callee.transferFromCalled());
    }
}

contract TransferFromOnlyCallee {
    bool public transferFromCalled;
    fallback(bytes calldata data) external returns (bytes memory) {
        if (bytes4(data) == 0x23b872dd) {
            transferFromCalled = true;
            return "";
        }
        revert("Unknown selector");
    }
}
